-- Sharawla POS — Point 4E-1 Authoritative Financial Journal source contract.
-- SOURCE ONLY: no operational workflow is connected and activation is false.
begin;
create table if not exists public.finance_journal_events_v1(
 id bigint generated by default as identity primary key,business_id bigint not null,branch_id bigint references public.branches(id) on delete restrict,
 event_type text not null check(event_type in('SALE','PAYMENT','REFUND','EXPENSE','CASH_MOVEMENT','SHIFT_SETTLEMENT','RECEIVABLE','COLLECTION','PAYABLE','SUPPLIER_PAYMENT','INVENTORY_VALUE','COGS','WASTE','DAMAGE','TRANSFER_VALUE','TRANSFER_VARIANCE','REVERSAL')),
 source_document_type text not null,source_document_id text not null,client_tx_id text not null,line_key text not null,
 operation_digest text not null check(operation_digest~'^[0-9a-f]{64}$'),currency_code text not null,
 reversal_of_event_id bigint unique references public.finance_journal_events_v1(id) on delete restrict,
 lineage jsonb not null check(jsonb_typeof(lineage)='object'),occurred_at timestamptz not null,recorded_at timestamptz not null default now(),
 unique(client_tx_id,line_key),unique(source_document_type,source_document_id,event_type,line_key),
 check(event_type='REVERSAL' or reversal_of_event_id is null),check(event_type<>'REVERSAL' or reversal_of_event_id is not null));
create table if not exists public.finance_journal_lines_v1(
 id bigint generated by default as identity primary key,event_id bigint not null references public.finance_journal_events_v1(id) on delete restrict,
 line_number integer not null check(line_number>0),account_code text not null,location_id bigint references public.branches(id) on delete restrict,
 counterparty_type text,counterparty_id text,debit numeric(18,4) not null default 0 check(debit>=0),credit numeric(18,4) not null default 0 check(credit>=0),
 quantity numeric(18,3),unit_cost numeric(18,4),stock_movement_id bigint references public.inventory_stock_movements_v2(id) on delete restrict,
 transfer_operation_id bigint references public.inventory_transfer_operations_v2(id) on delete restrict,
 payable_id bigint references public.supplier_payables_v1(id) on delete restrict,lineage jsonb not null check(jsonb_typeof(lineage)='object'),
 unique(event_id,line_number),check((debit>0 and credit=0) or (credit>0 and debit=0)));
create index if not exists finance_journal_events_source_v1 on public.finance_journal_events_v1(source_document_type,source_document_id);
create index if not exists finance_journal_lines_account_v1 on public.finance_journal_lines_v1(account_code,event_id);
create or replace function public.finance_journal_immutable_v1() returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'FINANCE_JOURNAL_V1_IMMUTABLE';end$$;
drop trigger if exists finance_journal_events_v1_immutable on public.finance_journal_events_v1;create trigger finance_journal_events_v1_immutable before update or delete on public.finance_journal_events_v1 for each row execute function public.finance_journal_immutable_v1();
drop trigger if exists finance_journal_lines_v1_immutable on public.finance_journal_lines_v1;create trigger finance_journal_lines_v1_immutable before update or delete on public.finance_journal_lines_v1 for each row execute function public.finance_journal_immutable_v1();
create or replace function public.finance_journal_assert_balanced_v1() returns trigger language plpgsql security definer set search_path='' as $$declare v_id bigint;v_debit numeric;v_credit numeric;v_original bigint;v_expected jsonb;v_actual jsonb;begin v_id:=coalesce(new.event_id,old.event_id);select coalesce(sum(debit),0),coalesce(sum(credit),0) into v_debit,v_credit from public.finance_journal_lines_v1 where event_id=v_id;if v_debit<=0 or v_debit<>v_credit then raise exception 'FINANCE_JOURNAL_V1_UNBALANCED';end if;select reversal_of_event_id into v_original from public.finance_journal_events_v1 where id=v_id;if v_original is not null then
 select jsonb_agg(jsonb_build_array(line_number,account_code,location_id,counterparty_type,counterparty_id,credit,debit) order by line_number) into v_expected from public.finance_journal_lines_v1 where event_id=v_original;
 select jsonb_agg(jsonb_build_array(line_number,account_code,location_id,counterparty_type,counterparty_id,debit,credit) order by line_number) into v_actual from public.finance_journal_lines_v1 where event_id=v_id;
 if v_actual is distinct from v_expected then raise exception 'FINANCE_JOURNAL_V1_REVERSAL_MISMATCH';end if;
end if;return null;end$$;
drop trigger if exists finance_journal_lines_v1_balanced on public.finance_journal_lines_v1;create constraint trigger finance_journal_lines_v1_balanced after insert or update or delete on public.finance_journal_lines_v1 deferrable initially deferred for each row execute function public.finance_journal_assert_balanced_v1();
create or replace function public.finance_journal_event_complete_v1() returns trigger language plpgsql security definer set search_path='' as $$declare v_debit numeric;v_credit numeric;v_lines bigint;v_original public.finance_journal_events_v1%rowtype;begin select count(*),coalesce(sum(debit),0),coalesce(sum(credit),0) into v_lines,v_debit,v_credit from public.finance_journal_lines_v1 where event_id=new.id;if v_lines<2 or v_debit<=0 or v_debit<>v_credit then raise exception 'FINANCE_JOURNAL_V1_EVENT_INCOMPLETE';end if;if new.reversal_of_event_id is not null then select * into strict v_original from public.finance_journal_events_v1 where id=new.reversal_of_event_id;if v_original.event_type='REVERSAL' or v_original.reversal_of_event_id is not null then raise exception 'FINANCE_JOURNAL_V1_REVERSAL_OF_REVERSAL';end if;if new.business_id<>v_original.business_id or new.branch_id is distinct from v_original.branch_id or upper(new.currency_code)<>upper(v_original.currency_code) then raise exception 'FINANCE_JOURNAL_V1_REVERSAL_SCOPE_MISMATCH';end if;end if;return null;end$$;
drop trigger if exists finance_journal_events_v1_complete on public.finance_journal_events_v1;create constraint trigger finance_journal_events_v1_complete after insert on public.finance_journal_events_v1 deferrable initially deferred for each row execute function public.finance_journal_event_complete_v1();
create or replace function public.finance_journal_point4e_activation_allowed_v1() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function public.finance_journal_intent_digest_v1(p_event_type text,p_client_tx_id text,p_line_key text,p_source_type text,p_source_id text,p_currency text,p_lines jsonb,p_reversal_of bigint) returns text language sql immutable security definer set search_path='' as $$select pg_catalog.encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object('schema_version',1,'event_type',p_event_type,'client_tx_id',btrim(p_client_tx_id),'line_key',p_line_key,'source_type',p_source_type,'source_id',p_source_id,'currency',upper(btrim(p_currency)),'lines',coalesce(p_lines,'[]'::jsonb),'reversal_of',p_reversal_of)::text,'UTF8'),'sha256'),'hex')$$;
create or replace function public.finance_journal_resolve_replay_v1(p_client_tx_id text,p_line_key text,p_digest text) returns bigint language plpgsql stable security definer set search_path='' as $$declare v public.finance_journal_events_v1%rowtype;begin select * into v from public.finance_journal_events_v1 where client_tx_id=p_client_tx_id and line_key=p_line_key;if not found then return null;end if;if v.operation_digest<>p_digest then raise exception 'FINANCE_JOURNAL_V1_IDEMPOTENCY_CONFLICT';end if;return v.id;end$$;
create or replace function public.finance_journal_assert_activation_v1() returns void language plpgsql stable security definer set search_path='' as $$begin if not public.finance_journal_point4e_activation_allowed_v1() then raise exception 'FINANCE_JOURNAL_V1_ACTIVATION_BLOCKED';end if;end$$;
alter table public.finance_journal_events_v1 enable row level security;alter table public.finance_journal_lines_v1 enable row level security;
revoke all on public.finance_journal_events_v1,public.finance_journal_lines_v1 from public,anon,authenticated;
revoke all on function public.finance_journal_immutable_v1() from public,anon,authenticated;revoke all on function public.finance_journal_assert_balanced_v1() from public,anon,authenticated;revoke all on function public.finance_journal_event_complete_v1() from public,anon,authenticated;revoke all on function public.finance_journal_point4e_activation_allowed_v1() from public,anon,authenticated;revoke all on function public.finance_journal_intent_digest_v1(text,text,text,text,text,text,jsonb,bigint) from public,anon,authenticated;revoke all on function public.finance_journal_resolve_replay_v1(text,text,text) from public,anon,authenticated;revoke all on function public.finance_journal_assert_activation_v1() from public,anon,authenticated;
comment on table public.finance_journal_events_v1 is 'Append-only Point 4 financial event contract. Source-only; no posting workflow is connected.';
commit;
